  "Handling time": "Behandlingstid",
  "handling time (minutes)": "håndteringstid (minutter)",
  "Handling time (minutes)": "Håndteringstid (minutter)",
  "handling time runs from submission to the final decision, including nights, weekends and time waiting. it is attributed to the final decision-maker; it does not measure active working time. averages count each application once and exclude missing or invalid timestamps. document totals count each selected type once per application, including archived records, not originals or copies. times are shown in uk time.": "håndtering af tid løber fra indsendelse til den endelige beslutning, herunder nætter, weekender og ventetid. Det tilskrives den endelige beslutningstager; det måler ikke aktiv arbejdstid. Gennemsnit tæller hver ansøgning én gang og udelukker manglende eller ugyldige tidsstempler. Dokumenttotaler tæller hver valgt type én gang pr program, herunder arkiverede optegnelser, ikke originale eller kopier. Tiderne vises i UK- tid.",
  "Handling time runs from submission to the final decision, including nights, weekends and time waiting. It is attributed to the final decision-maker; it does not measure active working time. Averages count each application once and exclude missing or invalid timestamps. Document totals count each selected type once per application, including archived records, not originals or copies. Times are shown in UK time.": "Håndtering af tid løber fra indsendelse til den endelige beslutning, herunder nætter, weekender og ventetid. Det tilskrives den endelige beslutningstager; det måler ikke aktiv arbejdstid. Gennemsnit tæller hver ansøgning én gang og udelukker manglende eller ugyldige tidsstempler. Dokumenttotaler tæller hver valgt type én gang pr program, herunder arkiverede optegnelser, ikke originale eller kopier. Tiderne vises i UK- tid.",
  "Handling time runs from submission to the final decision, including waiting time. It is attributed to the final decision-maker and does not measure active working time. Archived decisions are included. Missing or invalid times are excluded from averages.": "Håndteringstiden løber fra indsendelse til den endelige beslutning, herunder ventetid. Den tilskrives den endelige beslutningstager og måler ikke aktiv arbejdstid. Arkiverede beslutninger er inkluderet. Manglende eller ugyldige tidspunkter er udelukket fra gennemsnit.",
  "Handling time runs from submission to the final decision, including waiting time. It is attributed to the final decision-maker.": "Behandlingstiden løber fra indsendelse til endelig afgørelse, inklusive ventetid. Den registreres for den bruger, der træffer den endelige afgørelse.",
  "Handling time runs from submission to the recorded decision. It includes waiting time and does not measure active working time.": "Håndteringstiden løber fra indsendelse til den registrerede beslutning. Den omfatter ventetid og måler ikke den aktive arbejdstid.",
